import re

for s in ["cat", "cat food", "a cat", "concat"]:
    start = bool(re.search(r"^cat", s))
    end = bool(re.search(r"cat$", s))
    word = bool(re.search(r"\bcat\b", s))
    print(f"{s!r:11} ^:{start!s:6} $:{end!s:6} \\b:{word}")

